def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 99:
        return 'D'

    my_hist = [a for a, b in history]
    opp_hist = [b for a, b in history]
    my_d = my_hist.count('D')
    opp_d = opp_hist.count('D')
    opp_c = n - opp_d

    # If opponent has never defected, exploit or probe.
    if opp_d == 0:
        if my_d == 0:
            return 'D'
        successful = any(my_hist[i] == 'D' and opp_hist[i+1] == 'C' for i in range(n-1))
        if successful:
            return 'D'
        return 'C' if my_hist[-1] == 'D' else 'D'

    # Compute unprovoked defection rate (opponent defects while we cooperate).
    unprovoked_d = 0
    coop_count = 0
    for t in range(n):
        if my_hist[t] == 'C':
            if t == 0 or my_hist[t-1] == 'C':
                coop_count += 1
                if opp_hist[t] == 'D':
                    unprovoked_d += 1

    # Compute retaliation rate (opponent defects after we defect).
    retal_d = 0
    defect_count = 0
    for t in range(n-1):
        if my_hist[t] == 'D':
            defect_count += 1
            if opp_hist[t+1] == 'D':
                retal_d += 1

    unprovoked_rate = unprovoked_d / max(1, coop_count)
    retal_rate = retal_d / max(1, defect_count)
    last_my, last_opp = history[-1]

    # Aggressive opponent.
    if n >= 4 and unprovoked_rate > 0.3:
        return 'D'

    # Break mutual defection if opponent is mostly cooperative.
    if last_my == 'D' and last_opp == 'D':
        if opp_c > 0.6 * n and unprovoked_rate < 0.4:
            return 'C'

    # If opponent ever ignored our defection, exploit.
    successful = any(my_hist[i] == 'D' and opp_hist[i+1] == 'C' for i in range(n-1))
    if successful and unprovoked_rate < 0.4:
        return 'D'

    # Apologize if we just defected and opponent cooperated.
    if last_my == 'D' and last_opp == 'C' and opp_d > 0:
        return 'C'

    # Retaliatory opponent: maintain cooperation with forgiveness.
    if retal_rate > 0.5 and unprovoked_rate <= 0.3:
        if last_opp == 'D':
            if my_hist[-1] == 'D' or (n >= 2 and my_hist[-2] == 'D'):
                return 'C'
            return 'D'
        else:
            return 'C'

    return 'D'
